def settings_file_value(name, default=""):
    try:
        import json

        path = Path(SETTINGS_FILE)
        if not path.exists():
            return default
        settings = json.loads(path.read_text(encoding="utf-8-sig"))
        value = settings.get(name, default)
        return default if value is None else str(value)
    except Exception:
        return default


def load_local_tz():
    timezone_name = os.getenv("SPORTS_LOCAL_TIMEZONE", "America/Chicago")
    try:
        return ZoneInfo(timezone_name)
    except ZoneInfoNotFoundError:
        local_tz = datetime.now().astimezone().tzinfo
        if local_tz is not None:
            return local_tz
        return timezone(timedelta(hours=-5), "Central")


LOCAL_TZ = load_local_tz()
try:
    KALSHI_TZ = ZoneInfo("America/New_York")
    KALSHI_TZ_HAS_DST = True
except ZoneInfoNotFoundError:
    KALSHI_TZ = timezone(timedelta(hours=-5), "Eastern")
    KALSHI_TZ_HAS_DST = False


def kalshi_eastern_timezone(year, month, day, hour=0, minute=0):
    if KALSHI_TZ_HAS_DST:
        return KALSHI_TZ
    candidate = datetime(year, month, day, hour, minute)
    march_first = datetime(year, 3, 1)
    second_sunday_march = 8 + ((6 - march_first.weekday()) % 7)
    november_first = datetime(year, 11, 1)
    first_sunday_november = 1 + ((6 - november_first.weekday()) % 7)
    dst_start = datetime(year, 3, second_sunday_march, 2)
    dst_end = datetime(year, 11, first_sunday_november, 2)
    if dst_start <= candidate < dst_end:
        return timezone(timedelta(hours=-4), "Eastern Daylight")
    return KALSHI_TZ

