def sports_unit_steps(*, minimum=None, maximum=None):
    increment = max(0.001, float(SPORTS_UNIT_INCREMENT or 0.5))
    minimum = increment if minimum is None else max(increment, float(minimum))
    maximum = SPORTS_UNIT_MAX_PER_MARKET if maximum is None else max(0.0, float(maximum))
    first = max(1, int(math.ceil((minimum - 1e-9) / increment)))
    last = max(0, int(math.floor((maximum + 1e-9) / increment)))
    return [round(index * increment, 3) for index in range(first, last + 1)]


def sports_unit_key(value):
    number = round(float(value or 0), 3)
    return str(int(number)) if number.is_integer() else f"{number:g}"


def sports_unit_label(value):
    return f"{sports_unit_key(value)}u"


def configured_sports_unit_tiers():
    defaults = {
        1: (0.0, 70.0, 85.0, 80.0, 2),
        2: (1.0, 76.0, 90.0, 85.0, 2),
        3: (2.0, 82.0, 95.0, 89.0, 2),
        4: (4.0, 88.0, 100.0, 92.0, 2),
        5: (6.0, 92.0, 105.0, 95.0, 2),
    }
    whole_tiers = {}
    for units, values in defaults.items():
        edge, confidence, pro_score, final_score, book_families = values
        prefix = f"SPORTS_UNIT_{units}"
        whole_tiers[units] = {
            "units": units,
            "min_edge": float(os.getenv(
                f"{prefix}_MIN_EDGE",
                settings_file_value(f"{prefix}_MIN_EDGE", str(edge)),
            )),
            "min_confidence": float(os.getenv(
                f"{prefix}_MIN_CONFIDENCE",
                settings_file_value(f"{prefix}_MIN_CONFIDENCE", str(confidence)),
            )),
            "min_pro_score": float(os.getenv(
                f"{prefix}_MIN_PRO_SCORE",
                settings_file_value(f"{prefix}_MIN_PRO_SCORE", str(pro_score)),
            )),
            "min_final_score": float(os.getenv(
                f"{prefix}_MIN_FINAL_SCORE",
                settings_file_value(f"{prefix}_MIN_FINAL_SCORE", str(final_score)),
            )),
            "min_book_families": int(float(os.getenv(
                f"{prefix}_MIN_BOOK_FAMILIES",
                settings_file_value(f"{prefix}_MIN_BOOK_FAMILIES", str(book_families)),
            ))),
            "interpolated": False,
            "qualification_mode": "normal_live_entry",
        }
    tiers = {
        0.5: {
            **whole_tiers[1],
            "units": 0.5,
            "interpolated": False,
            "qualification_mode": "qualified_risk_reduction_only",
            "derived_from_units": [1],
        },
        **whole_tiers,
    }
    for lower_units in range(1, max(defaults)):
        upper_units = lower_units + 1
        lower = whole_tiers[lower_units]
        upper = whole_tiers[upper_units]
        midpoint = lower_units + 0.5
        tiers[midpoint] = {
            "units": midpoint,
            "min_edge": round((lower["min_edge"] + upper["min_edge"]) / 2.0, 3),
            "min_confidence": round((lower["min_confidence"] + upper["min_confidence"]) / 2.0, 3),
            "min_pro_score": round((lower["min_pro_score"] + upper["min_pro_score"]) / 2.0, 3),
            "min_final_score": round((lower["min_final_score"] + upper["min_final_score"]) / 2.0, 3),
            "min_book_families": max(lower["min_book_families"], upper["min_book_families"]),
            "interpolated": True,
            "qualification_mode": "normal_live_entry",
            "derived_from_units": [lower_units, upper_units],
        }
    return tiers


