def recovery_max_stake_pct_for_bankroll(bankroll):
    fallback = SPORTS_RECOVERY_MAX_STAKE_PCT
    for raw_tier in SPORTS_RECOVERY_MAX_STAKE_TIERS.split(","):
        if ":" not in raw_tier:
            continue
        raw_limit, raw_pct = [part.strip().lower() for part in raw_tier.split(":", 1)]
        try:
            limit = float("inf") if raw_limit in {"inf", "infinity", "*"} else float(raw_limit)
            pct = float(raw_pct)
        except ValueError:
            continue
        if bankroll <= limit:
            return pct
    return fallback

