def canonical_sport_key(sport_key):
    key = str(sport_key or "").strip()
    if key == "americanfootball_nfl_preseason":
        return "americanfootball_nfl"
    if key.startswith("tennis_atp"):
        return "tennis_atp"
    if key.startswith("tennis_wta"):
        return "tennis_wta"
    if key.startswith("tennis_itf"):
        return "tennis_itf"
    if key.startswith("mma_"):
        return "mma_mixed_martial_arts"
    if key.startswith("boxing_"):
        return "boxing_boxing"
    return key


DISABLED_BETTING_SPORTS = {"tennis_itf", "mma_mixed_martial_arts", "boxing_boxing"}
_TRUSTED_CAPPER_DISABLED_SPORT_CACHE = {"at": 0.0, "sports": set()}
_TRUSTED_CAPPER_ACTIVE_SPORT_CACHE = {"at": 0.0, "sports": set()}


def trusted_capper_ticket_provider_sports(ticket):
    """Resolve a broad capper sport to the ticket's matched provider league.

    Imported tickets intentionally use friendly family names such as ``soccer``
    and ``tennis``. Once schedule matching has identified the event, retaining
    that broad name makes every league in the family look like a priority paid
    odds refresh. The schedule snapshot is identity-checked elsewhere, so use
    its exact provider key and keep the family name only while a ticket is still
    unresolved.
    """
    requested = normalize_text((ticket or {}).get("sport_key")).replace(" ", "_")
    if not requested:
        return set()
    family_by_generic = {
        "soccer": "soccer",
        "tennis": "tennis",
        "mma": "mma",
        "boxing": "boxing",
    }
    requested_family = family_by_generic.get(requested)
    if not requested_family:
        return {requested}
    resolved = {
        str(game.get("sport_key") or "").strip()
        for game in (((ticket or {}).get("schedule_snapshot") or {}).get("games") or [])
        if isinstance(game, dict)
        and str(game.get("sport_key") or "").strip()
        and provider_sport_family(game.get("sport_key")) == requested_family
        and canonical_sport_key(game.get("sport_key")) != "tennis_itf"
    }
    return resolved or {requested}


def trusted_capper_active_sports():
    if time.monotonic() - float(_TRUSTED_CAPPER_ACTIVE_SPORT_CACHE.get("at") or 0) < 5.0:
        return set(_TRUSTED_CAPPER_ACTIVE_SPORT_CACHE.get("sports") or set())
    requested = set()
    if SPORTS_CAPPER_ENABLED:
        try:
            tickets = list_capper_tickets(limit=200, include_terminal=False)
        except Exception:
            tickets = []
        for ticket in tickets:
            if not ticket.get("executable", True):
                continue
            requested.update(trusted_capper_ticket_provider_sports(ticket))
    _TRUSTED_CAPPER_ACTIVE_SPORT_CACHE["at"] = time.monotonic()
    _TRUSTED_CAPPER_ACTIVE_SPORT_CACHE["sports"] = set(requested)
    return requested


def trusted_capper_watches_sport(sport_key):
    canonical = canonical_sport_key(sport_key)
    for requested in trusted_capper_active_sports():
        if requested == "tennis" and canonical.startswith("tennis_") and canonical != "tennis_itf":
            return True
        if requested == "soccer" and canonical.startswith("soccer_"):
            return True
        if requested == "mma" and canonical.startswith("mma_"):
            return True
        if canonical_sport_key(requested) == canonical:
            return True
    return False


def trusted_capper_watches_exact_sport(sport_key):
    """Return true only for an exact resolved provider league.

    Generic soccer/MMA requests still open broad discovery so a ticket can be
    identified, but they must not make every league an execution-priority
    five-minute refresh. Once the schedule snapshot resolves a league, that
    exact key receives the normal trusted-ticket cadence.
    """
    canonical = canonical_sport_key(sport_key)
    for requested in trusted_capper_active_sports():
        normalized = normalize_text(requested).replace(" ", "_")
        if normalized in {"soccer", "mma", "boxing"}:
            continue
        if normalized == "tennis" and canonical.startswith("tennis_") and canonical != "tennis_itf":
            return True
        if canonical_sport_key(requested) == canonical:
            return True
    return False


def trusted_capper_broad_discovery_sport(sport_key):
    """Identify provider leagues opened only by an unresolved family ticket."""
    canonical = canonical_sport_key(sport_key)
    active = trusted_capper_active_sports()
    if "soccer" in active and canonical.startswith("soccer_"):
        return not trusted_capper_watches_exact_sport(sport_key)
    if "mma" in active and canonical.startswith("mma_"):
        return not trusted_capper_watches_exact_sport(sport_key)
    if "boxing" in active and canonical.startswith("boxing_"):
        return not trusted_capper_watches_exact_sport(sport_key)
    return False


def trusted_capper_requested_disabled_sports():
    if time.monotonic() - float(_TRUSTED_CAPPER_DISABLED_SPORT_CACHE.get("at") or 0) < 5.0:
        return set(_TRUSTED_CAPPER_DISABLED_SPORT_CACHE.get("sports") or set())
    if not SPORTS_CAPPER_ENABLED:
        return set()
    requested = set()
    try:
        tickets = list_capper_tickets(limit=200, include_terminal=False)
    except Exception:
        return requested
    for ticket in tickets:
        if ticket.get("status") in {"placed", "cancelled", "expired", "unsupported", "manual_attention"}:
            continue
        if not ticket.get("executable", True):
            continue
        sport = normalize_text(ticket.get("sport_key")).replace(" ", "_")
        if sport == "mma":
            requested.add("mma_mixed_martial_arts")
        elif sport == "boxing":
            requested.add("boxing_boxing")
    _TRUSTED_CAPPER_DISABLED_SPORT_CACHE["at"] = time.monotonic()
    _TRUSTED_CAPPER_DISABLED_SPORT_CACHE["sports"] = set(requested)
    return requested


def kalshi_market_series_for_sports(sport_keys):
    series = []
    for sport_key in sport_keys or []:
        series.extend(KALSHI_MARKET_SERIES_BY_SPORT.get(canonical_sport_key(sport_key), ()))
    filtered = [
        item.upper()
        for item in series
        if item and not any(term in item.upper() for term in UNPRICED_KALSHI_SERIES_TERMS)
    ]
    return tuple(sorted(set(filtered)))
